  PanelText_UI_Events_OceanBoss_StageGroup_Text_C_Introduction_Content = {
    Text = "Bỏ rơi thân thể, bỏ rơi lý trí, trong thế giới ý chí thuần khiết này, cảm nhận sự hiện diện của Ngài.\nNgài là duy nhất của bạn. Ngài cũng là tất cả của bạn."
