  PanelText_UI_Events_Panel_ActivityPassport_Text_PayTip_Content = {
    Text = "Giá hiển thị hiện tại là giá bằng tiền tệ mặc định, chỉ để tham khảo. Khi thanh toán, hãy lấy tiền tệ và giá thực tế làm tiêu chuẩn."
