  PanelText_UI_Events_Panel_Arachne_StageGroup_Text_C_Introduction_Content = {
    Text = "Đèn sáng lên. Tiếng vỗ tay lắng xuống. Khán giả đang mong chờ.\nĐã đến lúc lên sân khấu rồi, những đứa con yêu dấu của ta. Hãy bước lên, hãy biểu diễn, hãy xé toạc tâm can, bán đi những bí mật sâu thẳm nhất. Hãy lấy những vết thương bi thảm nhất của các ngươi, làm thành món tráng miệng cho người ta thưởng thức. Hãy tham lam tận hưởng ánh đèn chỉ thắp sáng cho riêng ngươi trên sân khấu, cho đến khi bức màn chôn vùi ngươi cùng khán giả.\nĐây là sân khấu định mệnh của các ngươi, hãy bước lên! Đừng sợ hãi, không cần rụt rè."
  },
