  PanelText_UI_Events_Panel_Caraboo_StageGroup_Text_C_Introduction_Content = {
    Text = "♪~~♫~~♪~~♫~~♪~~♫~~\nDưới chân núi tuyết, mọi người dẫn đường đều ghi nhớ, mọi đứa trẻ đều truyền miệng. Đó là hiện thân ý chí của ngọn núi tuyết hùng vĩ, đó là thần nữ từ bi Umapati.\nThần lực của bà tản mát khắp nhân gian, bảo vật của bà không thể tìm thấy, chúng ở ngay trước mắt, chúng lại mờ mịt vô tăm tích. Hãy từ bỏ một điều gì đó, hãy kiên trì một điều gì đó.\nAi không thành tâm với chân thân của thần nữ, sẽ cùng với ngọn núi tuyết đã chết, mãi mãi chôn vùi trong núi tuyết."
  },
  PanelText_UI_Events_Panel_Caraboo_StageGroup_Text_C_Resonance_Content = {
    Text = "cảm ứng"
  },
  PanelText_UI_Events_Panel_Caraboo_StageGroup_Text_C_Title_Content = {
    Text = "Bảo Vật của Umapati"
  },
  PanelText_UI_Events_Panel_Caraboo_Text_C_ChallengeTip_Content = {
    Text = "Chế độ chơi mở trong thời gian giới hạn"
  },
