    Text = "Bảo Vật của Umapati"
  },
  PanelText_UI_Events_Panel_Caraboo_Text_C_RecordTip_Content = {
    Text = "Quyền truy cập miễn phí có hạn"
  },
  PanelText_UI_Events_Panel_Caraboo_Text_C_Record_Content = {
    Text = "Chiến dịch đặc biệt"
  },
  PanelText_UI_Events_Panel_Caraboo_Text_C_Reward_Content = {
    Text = "Phần thưởng thành tựu"
  },
  PanelText_UI_Events_Panel_Caraboo_Text_C_Shop_Content = {
    Text = "Điển Nghi Tiên Nữ"
  },
  PanelText_UI_Events_Panel_Caraboo_Text_C_Topic_Content = {
    Text = "Trăng Non và Tuyết Sâu"
  },
  PanelText_UI_Events_Panel_Castor_StageGroup_Text_C_Introduction_Content = {
    Text = "Cuộc đời của chú chim bay, định mệnh là một cuộc đời tự do. Bạn nên thấy được khoảnh khắc nó phá vỏ, giành lại tự do sống từ tay cái chết. Bạn nên thấy được lúc nó học bay, giành lại tự do sinh tồn độc lập từ tổ ấm an nhàn. Ngày nay nếu ném chìa khóa tự do vào vực sâu của cái chết, thì nó chắc chắn sẽ nhảy xuống không chút do dự, trong cuộc sống hẹp hòi và tự do vô hạn, chọn đối mặt với cơn bão của cái chết."
  },
