  PanelText_UI_Events_Panel_Clementine_StageGroup_Text_C_Introduction_Content = {
    Text = "Kể từ lúc đó, cô ấy không còn rơi một giọt nước mắt nào nữa. \nMột mình lang thang, lạc lối trong thế giới đầy dị loại. \nMột kế hoạch hoành tráng sắp bắt đầu, như là lời từ biệt cuối cùng của cô. \nCô là bác sĩ tâm lý thành công nhất, đây là lần điều trị thành công nhất của cô."
