  PanelText_UI_Events_Panel_Daffodil_StageGroup_Text_C_Introduction_Content = {
    Text = "Trong thị trấn ven biển này, có một con phố thương mại nhộn nhịp. Thương mại trên biển đã mang đến đây vô số hàng hóa mới mẻ, chỉ cần bạn trả đủ tiền Léofang, bạn sẽ luôn thu được những món hàng ưng ý. \n Chỉ có một cửa hàng nhỏ ở góc phố là ngoại lệ, đó là một cửa hàng đầy những cổ vật kỳ diệu, trong làn khói tỏa ra từ điếu thuốc, bà chủ đội mũ rộng vành sẽ từ từ nở một nụ cười với bạn. \n \"Chào mừng bạn đến cửa hàng giải sầu, nơi đây có thể đáp ứng mọi nhu cầu của bạn, chỉ cần bạn trả đủ thù lao…\" \n \"Tất nhiên, tất nhiên, giá cả hợp lý, không lừa dối người lớn trẻ nhỏ.\""
