  PanelText_UI_Events_Panel_KathiguRa_StageGroup_Text_C_Introduction_Content = {
    Text = "Cô ấy lại đứng vững trên Đất, sự báo thù tiêu diệt mọi thứ sẽ đến như đã hẹn. \n\n Đó là cuộc săn lùng không ngừng nghỉ, đó là ngọn lửa nóng bỏng của Chúa của Lửa Nổ. \n\n Cô ấy sẽ đi qua từng góc nhỏ, săn lùng tất cả những kẻ đã ký hợp đồng với tử thần. \n\n Hãy trốn đi, hãy trốn đi, hãy trốn vào những bóng tối sâu hơn, hãy trốn đến nơi mà bạn nghĩ sẽ không bị tìm thấy. \n\n Mặc dù điều đó vô nghĩa, vì Ngài cuối cùng sẽ bước qua mọi thế giới. \n\n Ngài sẽ săn lùng tất cả, cho đến khi mọi thứ trở thành tro tàn."
  },
