    Text = "Bầu trời~quang đãng~biển cả~yên tĩnh~\nMosk~bạn bè~viên than nhỏ~ra khơi!\ngió bão, không sợ, sấm sét, không sợ, Mosk, bạn bè, viên than nhỏ~\nVì tự do, phải·khởi·hành"
