  PanelText_UI_Events_Panel_Mouchette_StageGroup_Text_C_Introduction_Content = {
    Text = "Đột nhiên có một ngày, bạn phát hiện ra mình đã trở nên khác biệt. \n Không ai nhận ra điều này, vì bạn vẫn có những hành vi cử chỉ giống nhau, vẫn có vẻ đẹp rực rỡ như trước. \n Nhưng bạn rất rõ ràng, trái tim vốn đỏ tươi đã bị che phủ bởi một chiếc mặt nạ làm từ sương mù. \n \"Nếu tôi có thể giả vờ mãi như vậy, thì liệu tôi vẫn là chính tôi như trước đây không?\"\n Thật đáng mừng, câu hỏi này không ở lại trong đầu bạn quá một giây, bởi trước khi tháo chiếc mặt nạ đó ra, không ai biết được suy nghĩ thực sự của bạn. \n \"Vậy thì, hãy lên đường thôi~\""
  },
