  PanelText_UI_Events_Panel_OriDoll_StageGroup_Text_C_Introduction_Content = {
    Text = "Cô ấy nhìn chằm chằm vào cánh cửa lớn ở tận cùng thế giới, không chút do dự bước chân ra ngoài. \nCạch, cô vặn nắm đấm, nóng lòng nhìn về phía sau cánh cửa. \nTuy nhiên, phía sau cánh cửa trống rỗng, cô bước hụt chân, rơi vào hư vô. \nCô đã nên biết, quà tặng đến quá trực tiếp, thì luôn luôn sẽ có một cái giá đắt đỏ."
