    Text = "Lời hứa của thần đã gần kề.\nSau hàng ngàn năm chờ đợi, cái kết vui vẻ sắp đến, miền đất hứa sẽ mọc lên từ biển.\nThần sẽ sống lại từ ngực của Thần Mẹ, khi ngày thứ bảy kết thúc, một thế giới mới sẽ hạ xuống."
