    Text = "Giữa lý trí và sự sụp đổ, những bức tranh xảo trá từ từ được mở ra. \n Những ảo giác mà bạn khinh bỉ, vẽ nên những sắc màu lộng lẫy, \n sự mất kiểm soát mà bạn sợ hãi, tạo thành hình thức của sự trung thành. \n Ở đây, điên rồ là bản năng của nghệ thuật, là nguồn gốc của thế giới, \n là sự thật duy nhất không bao giờ nói dối."
