  PanelText_UI_Events_Panel_Saya_StageGroup_Text_C_Introduction_Content = {
    Text = "Khoa học, không quan trọng.\nLuân lý, không quan trọng.\nĐạo đức, không quan trọng.\nSinh mệnh, tử vong, hy vọng, tuyệt vọng... cuối cùng của cuối cùng, trên cuốn sổ tay dưới tầng hầm, hai nét chữ khác nhau để lại cùng một suy diễn.\nNgài nói: \"Nhìn đi, tình yêu là chủ đề duy nhất, vĩnh hằng.\""
