  PanelText_UI_Events_Panel_Sorel_StageGroup_Text_C_Introduction_Content = {
    Text = "Nhiều năm sau, nhà văn tiểu sử gõ cửa nhà cô ấy vào một buổi chiều. \n Hôm đó họ đã nói rất nhiều, từ đá mã não đến ngôi nhà hoa hồng héo tàn… \n Giờ đây, nhà văn đã biên soạn những lời nói vụn vặt này thành sách, dâng tặng cho tất cả mọi người có mặt ở đây."
