    Text = "Sextant cũ xác định góc giữa các vì sao, bản đồ biển cổ xưa xác định lộ trình dự kiến, chiếc la bàn cũ kỹ quyết định hướng đi…\nNgay cả khi ở trong Biển Đen sâu thẳm lạnh lẽo, vẫn có những nhà thám hiểm dựa vào đồng và sắt phàm tục để chỉ đường cho mọi người. \nMong rằng tất cả những người dẫn đường, đều không rơi vào sự mơ hồ."
